import React, { useEffect, useState } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchFallLocationWarnings,
  fetchFallLocationWarningStats,
  setFilters,
  setPage,
  deleteFallLocationWarning,
} from '../../store/slices/fallLocationWarningsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useResponsive } from '../../hooks/useResponsive';
import { FallWarningStatsCards } from './components/FallWarningStatsCards';
import { FallWarningFiltersBar } from './components/FallWarningFiltersBar';
import { FallWarningTable } from './components/FallWarningTable';
import { FallLocationWarning, FallLocationWarningFilters } from '../../models/FallLocationWarning';
import styles from './FallLocationWarningListPage.module.css';

import { Button, TableCard, Pagination } from '@linm-soft-org/linm-web-common-components';
const FallLocationWarningListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const dispatch    = useAppDispatch();
  const { isMobile } = useResponsive();

  const { items, loading, filters, pagination, stats } = useAppSelector((s) => s.fallLocationWarnings);
  const showLoading = useMinLoadingTime(loading);

  const [deleteConfirm, setDeleteConfirm] = useState<FallLocationWarning | null>(null);

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchFallLocationWarnings()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch, filters, pagination.page]);

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchFallLocationWarningStats()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch]);

  const handleFilterChange = (f: FallLocationWarningFilters) => {
    dispatch(setFilters(f));
    dispatch(setPage(1));
  };

  const handleClearFilters = () => {
    dispatch(setFilters({}));
    dispatch(setPage(1));
  };

  const handleCreate = () => appNavigate(scykRoutes.fallWarnings.new);

  const handleEdit = (item: FallLocationWarning) =>
    appNavigate(scykRoutes.fallWarnings.detail(item.id));

  const handleDeleteConfirm = async () => {
    if (!deleteConfirm) return;
    try {
      await dispatch(deleteFallLocationWarning(deleteConfirm.id)).unwrap();
      dispatch(addToast({ message: 'Đã xóa cảnh báo vị trí té ngã', type: 'success' }));
      dispatch(fetchFallLocationWarningStats());
    } catch {
      dispatch(addToast({ message: 'Lỗi khi xóa', type: 'error' }));
    }
    setDeleteConfirm(null);
  };

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-map-marker-alt" />
          {!isMobile && ' Cảnh Báo Vị Trí Té Ngã'}
        </h1>
        <Button variant="primary" onClick={handleCreate}>
          <i className="fas fa-plus" />
          {!isMobile && ' Thêm cảnh báo'}
        </Button>
      </div>

      {/* Stats */}
      <FallWarningStatsCards stats={stats} loading={showLoading} />

      {/* Table card */}
      <TableCard
        header={
          <FallWarningFiltersBar
            filters={filters}
            onChange={handleFilterChange}
            onClear={handleClearFilters}
            loading={showLoading}
          />
        }
        footer={
          <Pagination
            currentPage={pagination.page}
            totalPages={Math.ceil(Math.max(pagination.totalCount, 1) / pagination.pageSize)}
            totalCount={pagination.totalCount}
            pageSize={pagination.pageSize}
            onPageChange={(p) => dispatch(setPage(p))}
          />
        }
      >
        <FallWarningTable
          items={items}
          loading={showLoading}
          onEdit={handleEdit}
          onDelete={(item) => setDeleteConfirm(item)}
        />
      </TableCard>

      {/* Delete confirmation */}
      {deleteConfirm && (
        <div className={styles.overlay}>
          <div className={styles.dialog}>
            <h3>Xác nhận xóa</h3>
            <p>
              Bạn có chắc muốn xóa cảnh báo{' '}
              <strong>{deleteConfirm.idCode}</strong>?<br />
              Hành động này không thể hoàn tác.
            </p>
            <div className={styles.dialogActions}>
              <Button variant="secondary" onClick={() => setDeleteConfirm(null)}>Hủy</Button>
              <Button variant="danger" onClick={handleDeleteConfirm}>
                <i className="fas fa-trash" /> Xóa
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FallLocationWarningListPage;
