import React from 'react';
import {
  FallLocationWarning,
  FallWarningCurrentStatus,
  FallWarningProposalStatus,
} from '../../../models/FallLocationWarning';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './FallWarningTable.module.css';

import { Button, TwoLineTable, TwoLineTableColumn, TwoLineTableRow } from '@linm-soft-org/linm-web-common-components';
interface Props {
  items:    FallLocationWarning[];
  loading?: boolean;
  onEdit:   (item: FallLocationWarning) => void;
  onDelete: (item: FallLocationWarning) => void;
}

// ── Badge helpers ─────────────────────────────────────────────────────────────

const STATUS_CONFIG: Record<FallWarningCurrentStatus, { label: string; cls: string }> = {
  [FallWarningCurrentStatus.NotFixed]:   { label: 'Chưa khắc phục', cls: styles.badgeDanger  },
  [FallWarningCurrentStatus.InProgress]: { label: 'Đang khắc phục', cls: styles.badgeWarning },
  [FallWarningCurrentStatus.Fixed]:      { label: 'Đã khắc phục',   cls: styles.badgeSuccess },
};

const PROPOSAL_CONFIG: Record<FallWarningProposalStatus, { label: string; cls: string }> = {
  [FallWarningProposalStatus.NotProposed]: { label: 'Chưa đề xuất', cls: styles.badgeGray    },
  [FallWarningProposalStatus.Proposed]:    { label: 'Đã đề xuất',   cls: styles.badgePrimary },
};

const StatusBadge: React.FC<{ status: FallWarningCurrentStatus }> = ({ status }) => {
  const cfg = STATUS_CONFIG[status] ?? { label: status, cls: styles.badgeGray };
  return <span className={`${styles.badge} ${cfg.cls}`}>{cfg.label}</span>;
};

const ProposalBadge: React.FC<{ status: FallWarningProposalStatus }> = ({ status }) => {
  const cfg = PROPOSAL_CONFIG[status] ?? { label: status, cls: styles.badgeGray };
  return <span className={`${styles.badge} ${cfg.cls}`}>{cfg.label}</span>;
};

const fmt = (iso: string | null | undefined) =>
  iso ? new Date(iso).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '—';

// ── Columns ───────────────────────────────────────────────────────────────────

const columns: TwoLineTableColumn[] = [
  { key: 'surveyDate', label: 'Ngày khảo sát', width: '20%' },
  { key: 'department', label: 'Khoa / Phòng',  width: '25%' },
  { key: 'proposal',   label: 'Đề xuất',       width: '20%' },
  { key: 'createdBy',  label: 'Người tạo',     width: '35%' },
];

// ── Component ─────────────────────────────────────────────────────────────────

export const FallWarningTable: React.FC<Props> = ({ items, loading, onEdit, onDelete }) => {
  const { isMobile } = useResponsive();

  const rows: TwoLineTableRow<FallLocationWarning>[] = items.map((item) => ({
    id:   item.id,
    data: item,

    // Location code in the ID column
    idElement: (
      <span className={styles.locationCode}>{item.idCode}</span>
    ),

    // Line 1: location name + current status badge
    line1Content: (
      <>
        <span className={styles.locationName}>{item.location}</span>
        <StatusBadge status={item.currentStatus} />
      </>
    ),

    // Line 2: survey date | department | proposal | creator
    line2Cells: [
      <span>{fmt(item.surveyDate)}</span>,
      <span>{item.departmentName || <em className={styles.na}>—</em>}</span>,
      <ProposalBadge status={item.proposalStatus} />,
      <span>{item.createdByName}</span>,
    ],

    // Click-to-reveal action overlay
    actionsContent: (
      <div className={styles.actions}>
        <Button variant="secondary" onClick={() => onEdit(item)}>
          <i className="fas fa-edit" /> Sửa
        </Button>
        <Button variant="danger" onClick={() => onDelete(item)}>
          <i className="fas fa-trash" /> Xóa
        </Button>
      </div>
    ),
  }));

  return (
    <TwoLineTable
      columns={columns}
      rows={rows}
      loading={loading}
      emptyMessage={{
        icon:        'fas fa-map-marker-slash',
        title:       'Chưa có cảnh báo vị trí té ngã nào',
        description: 'Nhấn "Thêm cảnh báo" để ghi nhận vị trí nguy hiểm mới.',
      }}
      expandableActions
      isMobile={isMobile}
    />
  );
};
